using System;
using System.Text;

namespace TizenAmbilight
{
    /// <summary>
    /// In-app decoder self-check. A small 8x8 RGBA PNG (all five filter types, IDAT split
    /// across two chunks) was generated by an INDEPENDENT implementation — a hand-written
    /// Python/zlib encoder, see decoder-selftest/gen_testdata.py — and both the encoded
    /// bytes and the exact expected decoded pixel bytes are embedded here as literals.
    ///
    /// The TV app runs this once at startup and reports the verdict in its first stats POST,
    /// so the PNG decoder is proven working ON THE DEVICE, not only on the build host.
    /// The build host additionally runs decoder-selftest, which byte-compares against a
    /// larger set of generated files including a realistic 960x540 frame.
    /// </summary>
    public static class PngSelfTest
    {
        public const int Width = 8;
        public const int Height = 8;

        const string PngBase64 =
        "iVBORw0KGgoAAAANSUhEUgAAAAgAAAAICAYAAADED76LAAAAeUlEQVR42mOou6/z/2vX7/8ShWH/rx9Z+/9RscH/lXrn/8ek" +
        "Wv1/7fHwPyPb8S//xU/nMzi3VzPEF39n0PZfzJB+257h8vVuBn1mdwamjhcnGDQ4Mhg8VnQwvDihwcCR4cGwouMFwwkNDoYM" +
        "jxUMzOcd1BocuHoY0nYsYjiyeQ+B3wAAAHlJREFUz4DBqmYaw4ogE4Z3Cq8YctxmMLCATPiuDTHB/jLQBH1tBnfrFwzG24Em" +
        "JK9gYFBLF/m/dxPz/4ad//7Hryn9z1U94//Ha+H/XXST/n/eoPmfcZ3/nf/m2f0Mj5dLM9QLizOczndmaK+OZyj+rs3gvzid" +
        "sCMBaDBucvff+E4AAAAASUVORK5CYII=";

        const string ExpectedRgbaHex =
        "7edf2cfff58afbff187156ffd7c4adffe27330ffa92ecfff5c653affeb48e1ff06c7f4ff1d9263ff6019deffbf8cd5ff" +
        "eadb78ff51b6b7ff248d42ff539089ff8eafbcff459acbffa8c166ffa754fdfff243c0fff93e9fffecb54affbbd831ff" +
        "169784ff6da233fff069eeff8f1c25fffaab08ffa1c687ffb4dd52ff2320d9ff9e7f4cff95aa9bff381176ff77e44dff" +
        "021350ff494e6fff7c055aff8b6881ff266714ffbdb203ff80b9feff5fac75ff0a7b98fff1d657ff442d62fff3b029ff" +
        "ae4fdcffe5ba6bffc86186ff47749dff12e3e0ff995e3fff0c556aff5bf8d1ff3637a4ff0dc2d3ff10090eff2f3cc5ff" +
        "1a4b28ff41e627ffd47d72ffc34079ff";

        /// <summary>Returns a one-line verdict plus detail. Never throws.</summary>
        public static string Run()
        {
            try
            {
                byte[] png = Convert.FromBase64String(PngBase64.Replace("\n", "").Replace(" ", ""));
                byte[] expected = FromHex(ExpectedRgbaHex);

                PngImage img = PngDecoder.Decode(png);

                if (img.Width != Width || img.Height != Height)
                    return "FAIL: dimensions " + img.Width + "x" + img.Height +
                           ", expected " + Width + "x" + Height;

                if (img.Rgba == null || img.Rgba.Length != expected.Length)
                    return "FAIL: decoded " + (img.Rgba == null ? 0 : img.Rgba.Length) +
                           " bytes, expected " + expected.Length;

                int firstDiff = -1;
                for (int i = 0; i < expected.Length; i++)
                    if (img.Rgba[i] != expected[i]) { firstDiff = i; break; }

                if (firstDiff >= 0)
                    return "FAIL: byte " + firstDiff + " decoded 0x" + img.Rgba[firstDiff].ToString("x2") +
                           ", expected 0x" + expected[firstDiff].ToString("x2");

                return "PASS: " + Width + "x" + Height + " RGBA, " + expected.Length +
                       " bytes identical to the reference decode (all 5 PNG filter types, split IDAT)";
            }
            catch (Exception e)
            {
                return "FAIL: " + e.GetType().Name + ": " + e.Message;
            }
        }

        static byte[] FromHex(string hex)
        {
            byte[] b = new byte[hex.Length / 2];
            for (int i = 0; i < b.Length; i++)
                b[i] = (byte)Convert.ToInt32(hex.Substring(i * 2, 2), 16);
            return b;
        }
    }
}
